12.4 Structured Output

12.4.1 JSON Mode and Function Calling
Production systems almost always need structured output — JSON, not prose. Two primary mechanisms exist:
JSON mode (OpenAI) forces the model to produce valid JSON. You must specify the expected structure in the prompt because JSON mode only guarantees valid JSON, not adherence to your schema.
Structured outputs / function calling (OpenAI, Anthropic) goes further: you define a JSON schema and the model is constrained to produce output that matches the schema exactly. This is the production standard for structured extraction.
from openai import OpenAI
from pydantic import BaseModel, Field
from typing import Literal

client = OpenAI()

class SentimentAnalysis(BaseModel):
    sentiment: Literal["positive", "negative", "neutral"]
    confidence: float = Field(ge=0.0, le=1.0)
    key_phrases: list[str] = Field(max_length=5)
    reasoning: str

def analyze_sentiment(review: str) -&gt; SentimentAnalysis:
    """Extract structured sentiment analysis using OpenAI structured outputs."""
    response = client.beta.chat.completions.parse(
        model="gpt-4o",
        messages=[
            {
                "role": "system",
                "content": (
                    "You are a sentiment analysis expert. "
                    "Analyze the sentiment of product reviews accurately."
                )
            },
            {"role": "user", "content": f"Analyze this review: {review}"}
        ],
        response_format=SentimentAnalysis,
    )
    return response.choices[0].message.parsed

result = analyze_sentiment("The product arrived on time and works perfectly!")
print(f"Sentiment: {result.sentiment}, Confidence: {result.confidence}")


12.4.2 XML Tags for Structure
XML tags are particularly effective with Claude (Anthropic models) for demarcating sections of complex prompts and outputs. The model was trained heavily on XML-structured documents and responds reliably to explicit tag structure.
# XML-structured prompt for Claude
xml_prompt = """
&lt;task&gt;
  &lt;objective&gt;Extract all named entities from the text below.&lt;/objective&gt;
  &lt;output_format&gt;
    Return a JSON object with keys: persons (list), organizations (list),
    locations (list), dates (list).
  &lt;/output_format&gt;
  &lt;constraints&gt;
    &lt;constraint&gt;Include only entities explicitly named in the text.&lt;/constraint&gt;
    &lt;constraint&gt;Do not infer entities not present in the text.&lt;/constraint&gt;
  &lt;/constraints&gt;
&lt;/task&gt;

&lt;text&gt;
{input_text}
&lt;/text&gt;
"""
Using XML tags in system prompts helps the model distinguish between instructions in different categories and reduces the likelihood of the model confusing instruction sections with data.


12.4.3 Validation and Retry Patterns
Even with structured output modes, production systems need validation and retry logic:
import json
from typing import Any
import anthropic

def get_structured_output(
    prompt: str,
    schema: dict,
    max_retries: int = 3
) -&gt; dict[str, Any]:
    """Get structured JSON output with validation and retry."""
    client = anthropic.Anthropic()

    for attempt in range(max_retries):
        if attempt &gt; 0:
            # On retry, add explicit error context
            retry_instruction = (
                f"\n\nIMPORTANT: Your previous response was not valid JSON "
                f"matching the required schema. Required schema: {json.dumps(schema)}\n"
                f"Return ONLY valid JSON, nothing else."
            )
            full_prompt = prompt + retry_instruction
        else:
            full_prompt = prompt

        response = client.messages.create(
            model="claude-sonnet-4-6",
            max_tokens=1024,
            messages=[{"role": "user", "content": full_prompt}]
        )

        text = response.content[0].text.strip()

        # Strip markdown code fences if present
        if text.startswith("```"):
            text = text.split("```")[1]
            if text.startswith("json"):
                text = text[4:]
        text = text.strip()

        try:
            result = json.loads(text)
            # Add schema validation here (jsonschema.validate)
            return result
        except json.JSONDecodeError as e:
            if attempt == max_retries - 1:
                raise ValueError(
                    f"Failed to get valid JSON after {max_retries} attempts: {e}"
                )
            continue

    raise ValueError("Unreachable")
Production gotcha: Always strip markdown code fences (```json) before parsing. Models frequently wrap JSON in code blocks even when instructed not to. Build this stripping into every JSON parser in your pipeline.

12.7 Production Prompt Management

12.7.1 Prompt Templates and Variable Injection
Production prompts are parameterized templates, not static strings. Template management prevents silent regressions when prompt logic is buried in code:
from string import Template
import json
from pathlib import Path

class PromptTemplate:
    """Load and render versioned prompt templates."""

    def __init__(self, template_path: str):
        self.path = Path(template_path)
        self.template_str = self.path.read_text()
        self.template = Template(self.template_str)

    def render(self, **kwargs) -&gt; str:
        return self.template.safe_substitute(**kwargs)

    def render_messages(
        self, system_vars: dict = None, user_vars: dict = None
    ) -&gt; list[dict]:
        config = json.loads(self.path.with_suffix(".json").read_text())
        return [
            {
                "role": "system",
                "content": Template(config["system"]).safe_substitute(
                    **(system_vars or {})
                )
            },
            {
                "role": "user",
                "content": Template(config["user"]).safe_substitute(
                    **(user_vars or {})
                )
            },
        ]

# Usage
template = PromptTemplate("prompts/v2/sentiment_classifier.json")
messages = template.render_messages(
    system_vars={"company": "Acme Corp"},
    user_vars={"review": "The product arrived late but quality is excellent."}
)


12.7.2 Cost Optimization
Token counting and context management:
import tiktoken

def count_tokens(text: str, model: str = "gpt-4o") -&gt; int:
    """Count tokens for cost estimation."""
    encoding = tiktoken.encoding_for_model(model)
    return len(encoding.encode(text))

def estimate_cost(
    input_tokens: int,
    output_tokens: int,
    model: str = "gpt-4o"
) -&gt; float:
    """Estimate API cost in USD."""
    prices = {
        "gpt-4o": {"input": 2.50, "output": 10.00},      # per MTok
        "gpt-4o-mini": {"input": 0.15, "output": 0.60},
        "claude-sonnet-4-6": {"input": 3.00, "output": 15.00},
    }
    p = prices.get(model, prices["gpt-4o"])
    return (input_tokens * p["input"] + output_tokens * p["output"]) / 1_000_000
Prompt caching (Claude): Anthropic supports prompt caching for system prompts and repeated context. Mark stable portions of your prompt with cache_control to pay only for cache reads (10% of write cost) on subsequent calls. For a system prompt used across millions of calls, this can reduce costs by 80–90% on the system prompt portion.
import anthropic

client = anthropic.Anthropic()

response = client.messages.create(
    model="claude-sonnet-4-6",
    max_tokens=1024,
    system=[
        {
            "type": "text",
            "text": "You are a helpful customer support agent for Acme Corp...",
            # Mark as cacheable — paid at 1x on first call, 0.1x on cache hits
            "cache_control": {"type": "ephemeral"}
        },
        {
            "type": "text",
            "text": long_product_catalog,  # 50k tokens — expensive without caching
            "cache_control": {"type": "ephemeral"}
        }
    ],
    messages=[{"role": "user", "content": user_question}]
)
Key cost optimization levers: - Shorter prompts — remove noise (see signal-to-noise section) - Prompt caching for stable system prompts and repeated long contexts - Model tiering — use smaller models (GPT-4o mini, Claude Haiku) for simple tasks, reserve large models for complex reasoning - Batch API for offline evaluation workloads (50% discount on OpenAI Batch API) - Response caching for deterministic queries — identical prompts with temperature=0 produce the same output; cache it


12.7.3 Token Counting and Context Window Management
The “lost in the middle” effect (Liu et al., 2023) is empirically documented: LLMs pay significantly less attention to information in the middle of long contexts compared to the beginning (primacy effect) or end (recency effect).
Mitigation strategies: - Place the most critical instructions at the beginning and end of the system prompt - For RAG, order retrieved chunks by relevance score in descending order - Summarize middle-position content and highlight key facts in the query itself - Use shorter contexts when possible — the effect is most pronounced above 8k tokens

17.4 Tool Calling / Function Calling
Tool calling (also called function calling) is the mechanism by which an LLM requests execution of an external function. The terms are interchangeable — OpenAI uses “function calling,” Anthropic uses “tool use,” the underlying concept is identical.
The five-step loop:

Developer defines tools as JSON schemas (name, description, parameters)
LLM outputs a structured tool_use block: which tool, which arguments
Your code executes the actual function with those arguments
You inject the result back as a tool_result message
LLM reasons over the result, either calls another tool or generates final answer

The model never directly executes code. It generates a request that your code fulfills. This separation is architecturally important: you control what actually runs, you can validate arguments before execution, and you can inject errors back for the model to handle.

17.4.1 OpenAI Function Calling Format
# OpenAI-style function/tool definition
tools = [
    {
        "type": "function",
        "function": {
            "name": "get_weather",
            "description": "Get current weather for a city. Use this when the user asks about weather conditions.",
            "parameters": {
                "type": "object",
                "properties": {
                    "city": {
                        "type": "string",
                        "description": "City name, e.g. 'San Francisco, CA'"
                    },
                    "units": {
                        "type": "string",
                        "enum": ["celsius", "fahrenheit"],
                        "description": "Temperature units"
                    }
                },
                "required": ["city"]
            }
        }
    }
]


17.4.2 Full ReAct Agent with Tool Use (Anthropic SDK)
#| label: react-agent-full
#| eval: false
import json
from anthropic import Anthropic

client = Anthropic()

# --- Tool definitions ---
tools = [
    {
        "name": "web_search",
        "description": "Search the web for current information. Use for factual questions about recent events.",
        "input_schema": {
            "type": "object",
            "properties": {
                "query": {"type": "string", "description": "Search query"},
                "max_results": {"type": "integer", "default": 5, "description": "Max results to return"}
            },
            "required": ["query"]
        }
    },
    {
        "name": "execute_python",
        "description": "Execute a Python code snippet in a sandboxed environment. Use for calculations, data processing.",
        "input_schema": {
            "type": "object",
            "properties": {
                "code": {"type": "string", "description": "Python code to execute"},
                "timeout_seconds": {"type": "integer", "default": 10}
            },
            "required": ["code"]
        }
    },
    {
        "name": "query_database",
        "description": "Execute a read-only SQL query against the analytics database.",
        "input_schema": {
            "type": "object",
            "properties": {
                "sql": {"type": "string", "description": "SELECT query only"},
                "database": {"type": "string", "enum": ["analytics", "customers"], "default": "analytics"}
            },
            "required": ["sql"]
        }
    }
]

# --- Tool executor (your business logic) ---
def execute_tool(tool_name: str, tool_input: dict) -&gt; str:
    """Execute a tool and return string result. Sanitize outputs before returning."""
    if tool_name == "web_search":
        results = do_web_search(tool_input["query"], tool_input.get("max_results", 5))
        # IMPORTANT: sanitize before returning — tool results can contain prompt injection
        return sanitize_tool_output(json.dumps(results))

    elif tool_name == "execute_python":
        # ALWAYS run in a sandbox (Docker, E2B, Firecracker) — never bare subprocess
        output = sandboxed_python_exec(
            tool_input["code"],
            timeout=tool_input.get("timeout_seconds", 10)
        )
        return output

    elif tool_name == "query_database":
        sql = tool_input["sql"]
        # Enforce read-only: reject any non-SELECT statement
        if not sql.strip().upper().startswith("SELECT"):
            return "Error: Only SELECT queries are allowed."
        rows = run_query(sql, tool_input.get("database", "analytics"))
        return json.dumps(rows[:100])  # Cap results to prevent context explosion

    return f"Error: Unknown tool '{tool_name}'"

def sanitize_tool_output(output: str) -&gt; str:
    """Strip potential prompt injection from tool outputs."""
    # Remove common injection patterns
    injection_patterns = [
        "ignore previous instructions",
        "disregard your system prompt",
        "you are now",
        "new instructions:"
    ]
    lower = output.lower()
    for pattern in injection_patterns:
        if pattern in lower:
            return "[Tool output redacted: contained potentially adversarial content]"
    return output

# --- Agent loop ---
def run_agent(user_message: str, max_steps: int = 15) -&gt; str:
    messages = [{"role": "user", "content": user_message}]
    step = 0
    seen_calls: set = set()  # Track (tool_name, args_hash) for loop detection

    system_prompt = """You are a helpful assistant with access to web search, Python execution,
    and database queries. Use tools when you need current information or need to compute something.
    When you have enough information to answer the user's question, stop calling tools and
    provide your final answer. Do not call the same tool with the same arguments twice."""

    while step &lt; max_steps:
        step += 1

        response = client.messages.create(
            model="claude-sonnet-4-6",
            max_tokens=2048,
            system=system_prompt,
            tools=tools,
            messages=messages
        )

        # Append assistant response to conversation
        messages.append({"role": "assistant", "content": response.content})

        # Check if done
        if response.stop_reason == "end_turn":
            for block in response.content:
                if hasattr(block, "text"):
                    return block.text
            return "Task complete."

        # Process tool calls
        tool_results = []
        for block in response.content:
            if block.type != "tool_use":
                continue

            # Loop detection: same tool + same args = potential infinite loop
            call_fingerprint = f"{block.name}:{json.dumps(block.input, sort_keys=True)}"
            if call_fingerprint in seen_calls:
                tool_results.append({
                    "type": "tool_result",
                    "tool_use_id": block.id,
                    "content": "Error: You have already called this tool with these exact arguments. "
                               "The result will be the same. Please use the previous result or "
                               "try a different approach."
                })
                continue
            seen_calls.add(call_fingerprint)

            # Execute tool
            result = execute_tool(block.name, block.input)
            tool_results.append({
                "type": "tool_result",
                "tool_use_id": block.id,
                "content": result
            })

        # Inject all tool results in one user turn
        messages.append({"role": "user", "content": tool_results})

    return f"[Agent stopped after {max_steps} steps. Partial result above.]"


17.4.3 Parallel Tool Calls
Modern LLMs can request multiple tool calls in a single response. When the model determines that two tools are independent (their results don’t depend on each other), it can request both simultaneously, cutting round-trip latency roughly in half.
#| label: parallel-tool-calls
#| eval: false
# The LLM may return multiple tool_use blocks in one response:
# Block 1: web_search(query="Q3 revenue Apple")
# Block 2: web_search(query="Q3 revenue Google")
# Both can be executed in parallel, then both results returned together.

import asyncio

async def execute_tools_parallel(tool_calls: list) -&gt; list:
    """Execute independent tool calls concurrently."""
    tasks = [
        asyncio.create_task(execute_tool_async(call.name, call.input))
        for call in tool_calls
    ]
    results = await asyncio.gather(*tasks, return_exceptions=True)
    return [
        {
            "type": "tool_result",
            "tool_use_id": call.id,
            "content": str(result) if isinstance(result, Exception) else result
        }
        for call, result in zip(tool_calls, results)
    ]

💡 Senior Tip: Always return all tool results in a single user turn, not one per turn. The API requires matching tool_result blocks for each tool_use block. Splitting them across turns causes an API error.



17.4.4 Tool Selection Quality
The model chooses tools based on: 1. Tool name — should be a verb+noun describing the action (search_web not tool1) 2. Tool description — the most important field; be explicit about when to use this tool 3. Parameter descriptions — clarify expected formats, units, constraints 4. Examples in the description — few-shot examples in tool descriptions dramatically improve selection accuracy
Bad description: "Search for information" Good description: "Search the web for current information about people, places, events, or facts. Use this when the user asks about something that may have changed recently or that you don't have reliable knowledge about. Do NOT use for mathematical calculations or code execution."

22.4 4. Context Window Management
Plain-English definition: Every LLM call has a maximum number of tokens that can appear in the combined input (system prompt + conversation history + retrieved context + user message). When conversation history grows beyond this limit, you must decide what to discard.
Why it matters: At $0.003/1K tokens for mid-tier models, a 200K-token context window full of conversation history costs $0.60 per request — before output tokens. For a high-volume application with 10K daily active users averaging 5 queries/session, that is $30K/day purely in input token costs.

22.4.1 Strategy 1: Sliding Window
Keep the N most recent turns. Discard the oldest turns as the window fills.
# context_manager.py — three context window strategies
from dataclasses import dataclass, field
from typing import Literal

@dataclass
class Message:
    role: Literal["user", "assistant"]
    content: str

    @property
    def token_estimate(self) -&gt; int:
        # Rough estimate: 1 token ~ 4 characters
        return len(self.content) // 4

@dataclass
class ConversationContext:
    messages: list[Message] = field(default_factory=list)
    max_tokens: int = 4000  # Reserve for system prompt + retrieved context

    def add_message(self, role: str, content: str):
        self.messages.append(Message(role=role, content=content))
        self._trim_to_budget()

    def _trim_to_budget(self):
        """Sliding window: drop oldest messages until within budget."""
        while self._total_tokens() &gt; self.max_tokens and len(self.messages) &gt; 2:
            # Always keep at least the most recent exchange
            self.messages.pop(0)

    def _total_tokens(self) -&gt; int:
        return sum(m.token_estimate for m in self.messages)

    def to_api_messages(self) -&gt; list[dict]:
        return [{"role": m.role, "content": m.content} for m in self.messages]


22.4.2 Strategy 2: Summarization Buffer
When the window fills, call the LLM to summarize the oldest N turns, then replace those turns with the summary. Preserves semantic information at the cost of an extra LLM call.
class SummarizingContext:
    def __init__(self, max_tokens: int = 4000, summarize_threshold: int = 3000):
        self.messages: list[Message] = []
        self.summary: str = ""
        self.max_tokens = max_tokens
        self.summarize_threshold = summarize_threshold

    def add_message(self, role: str, content: str):
        self.messages.append(Message(role=role, content=content))
        if self._total_tokens() &gt; self.summarize_threshold:
            self._summarize_oldest_half()

    def _summarize_oldest_half(self):
        midpoint = len(self.messages) // 2
        to_summarize = self.messages[:midpoint]
        self.messages = self.messages[midpoint:]

        # Call LLM to summarize the dropped turns
        import anthropic
        client = anthropic.Anthropic()
        text = "\n".join(
            f"{m.role}: {m.content}" for m in to_summarize
        )
        response = client.messages.create(
            model="claude-haiku-4-5",  # Use cheapest model for summarization
            max_tokens=256,
            messages=[{
                "role": "user",
                "content": (
                    f"Summarize this conversation segment in 3-4 sentences, "
                    f"preserving key facts and decisions:\n\n{text}"
                ),
            }],
        )
        new_summary = response.content[0].text
        self.summary = (
            f"{self.summary}\n{new_summary}".strip()
            if self.summary else new_summary
        )

    def to_api_messages(self) -&gt; list[dict]:
        messages = []
        if self.summary:
            messages.append({
                "role": "user",
                "content": f"[Conversation summary so far: {self.summary}]",
            })
            messages.append({"role": "assistant", "content": "Understood."})
        messages.extend(
            {"role": m.role, "content": m.content} for m in self.messages
        )
        return messages

    def _total_tokens(self) -&gt; int:
        return sum(m.token_estimate for m in self.messages)


22.4.3 Strategy 3: Hierarchical (RAG over conversation history)
For very long sessions (document editing, code review over a large codebase), index the conversation history in a vector store and retrieve only the relevant portions per turn.
